     1→import { beforeEach, describe, expect, it } from "vitest";
     2→import { createTabNavigationState } from "@/navigation/tab-navigation";
     3→import { locationToUrl, type BreadcrumbStackItem, type DesktopLocation, type TabNavigationState } from "@/navigation/navigation-meta";
     4→import {
     5→  TAB_STORE_STORAGE_KEY,
     6→  getTabCurrentLeaf,
     7→  getTabCurrentState,
     8→  getTabUrl,
     9→  getTabViewModel,
    10→  mergePersistedTabState,
    11→  useTabStore,
    12→  type ClosedTabSnapshot,
    13→  type PageTab,
    14→} from "./tab-store";
    15→
    16→const FORBIDDEN_PAGE_TAB_FIELDS = [
    17→  "label",
    18→  "icon",
    19→  "descriptorId",
    20→  "meta",
    21→  "target",
    22→  "sourceNodeId",
    23→  "parentNodeId",
    24→  "history",
    25→] as const;
    26→
    27→function item(
    28→  id: string,
    29→  label: string,
    30→  location: DesktopLocation,
    31→  meta?: BreadcrumbStackItem["meta"]
    32→): BreadcrumbStackItem {
    33→  const canonicalUrl = locationToUrl(location);
    34→  return {
    35→    id,
    36→    label,
    37→    descriptorId: id,
    38→    meta,
    39→    target: {
    40→      key: canonicalUrl,
    41→      location,
    42→      canonicalUrl,
    43→    },
    44→  };
    45→}
    46→
    47→function state(
    48→  location: DesktopLocation,
    49→  breadcrumbStack: BreadcrumbStackItem[]
    50→): TabNavigationState {
    51→  return createTabNavigationState(location, breadcrumbStack);
    52→}
    53→
    54→function documentsState(): TabNavigationState {
    55→  const location: DesktopLocation = { kind: "documents" };
    56→  return state(location, [item("documents", "Documents", location)]);
    57→}
    58→
    59→function settingsState(section: "general" | "about"): TabNavigationState {
    60→  const location: DesktopLocation = { kind: "settings", section };
    61→  return state(location, [item("settings", section === "general" ? "General" : "About", location)]);
    62→}
    63→
    64→function workspaceAgentsState(workspaceId = "workspace-a"): TabNavigationState {
    65→  const location: DesktopLocation = {
    66→    kind: "workspace-section",
    67→    workspaceId,
    68→    section: "agent",
    69→  };
    70→  return state(location, [
    71→    item("workspace", "Workspace A", { kind: "workspace-home", workspaceId }, { workspaceId }),
    72→    item("workspace-section:agent", "智能体", location, { workspaceId, section: "agent" }),
    73→  ]);
    74→}
    75→
    76→function agentDetailState(workspaceId = "workspace-a", agentId = "agent-a"): TabNavigationState {
    77→  const location: DesktopLocation = {
    78→    kind: "workspace-agent-detail",
    79→    workspaceId,
    80→    agentId,
    81→  };
    82→  return state(location, [
    83→    ...workspaceAgentsState(workspaceId).breadcrumbStack,
    84→    item("workspace-agent", "个人助手", location, { workspaceId, agentId }),
    85→  ]);
    86→}
    87→
    88→function makeTab(partial: {
    89→  id: string;
    90→  pinned?: boolean;
    91→  historyIndex?: number;
    92→  navigationHistory?: TabNavigationState[];
    93→  viewMode?: PageTab["viewMode"];
    94→}): PageTab {
    95→  return {
    96→    id: partial.id,
    97→    pinned: partial.pinned ?? false,
    98→    historyIndex: partial.historyIndex ?? 0,
    99→    navigationHistory: partial.navigationHistory ?? [documentsState()],
   100→    viewMode: partial.viewMode,
   101→  };
   102→}
   103→
   104→function makeClosedSnapshot(tab: PageTab, originIndex: number): ClosedTabSnapshot {
   105→  return {
   106→    tab,
   107→    originIndex,
   108→    closedAt: Date.now(),
   109→  };
   110→}
   111→
   112→function expectNoRemovedPageTabFields(tab: PageTab) {
   113→  for (const field of FORBIDDEN_PAGE_TAB_FIELDS) {
   114→    expect(tab).not.toHaveProperty(field);
   115→  }
   116→}
   117→
   118→function mergePersisted(input: {
   119→  tabs?: unknown[];
   120→  activeTabId?: string | null;
   121→  recentlyClosedTabs?: unknown[];
   122→}) {
   123→  return mergePersistedTabState(
   124→    {
   125→      tabs: input.tabs as PageTab[] | undefined,
   126→      activeTabId: input.activeTabId ?? null,
   127→      recentlyClosedTabs: input.recentlyClosedTabs as ClosedTabSnapshot[] | undefined,
   128→    },
   129→    {
   130→      tabs: [],
   131→      activeTabId: null,
   132→      recentlyClosedTabs: [],
   133→    }
   134→  );
   135→}
   136→
   137→describe("tab-store target navigation state architecture", () => {
